import test from 'node:test';
import assert from 'node:assert/strict';
import {DELIVERY_HISTORY_KEY,readDeliveryHistory,saveDeliveryBatch,deliveryHistoryUrl,deliveryBatchCsv,mountDeliveryHistory,deliveryBatchOutcome,filterDeliveryHistory,deliveryBatchLinks,deliveryVersionCheckIncidents,deliveryHistoryBackup,compareDeliveryBatchTargets,deliveryComparisonCsv,deliveryComparisonSummary} from '../assets/interactive-delivery-history.mjs';
const action=(entry,name)=>entry.children.find(n=>n.className==='history-batch-actions').children.find(n=>n.className===name);
const store=()=>{const map=new Map([['project-library','unchanged']]);return{map,getItem:k=>map.get(k)??null,setItem:(k,v)=>map.set(k,v)};};
const result=(id='venue',status='success')=>({locationId:id,locationName:id,screenId:'touch',screenName:'Panel táctil',status,url:'https://www.admira.store/xpacios/pantalla/?loc='+id+'&screen=touch&ainimation='+'a'.repeat(64),token:'must-not-persist',project:{private:'not metadata'},message:'token must not persist'});
const batch=(id='batch-1',results=[result()])=>({id,projectId:'project-1',projectTitle:'Prueba',revision:8,createdAt:'2026-10-22T19:00:00Z',updatedAt:'2026-10-22T19:00:00Z',results,token:'secret',project:{private:'content'},owner:'private-owner'});
test('conserva cinco resultados tras una lectura nueva y guarda sólo metadatos sin identidad, credenciales ni contenido',()=>{const s=store(),b=batch('batch-1',Array.from({length:5},(_,i)=>result('venue-'+i)));assert.equal(saveDeliveryBatch(s,b).ok,true);const read=readDeliveryHistory(s);assert.equal(read.ok,true);assert.equal(read.data[0].results.length,5);assert.equal(read.data[0].revision,8);const raw=s.map.get(DELIVERY_HISTORY_KEY);for(const forbidden of ['token','secret','owner','private','content','message'])assert.ok(!raw.includes(forbidden),forbidden);assert.equal(s.map.get('project-library'),'unchanged');});
test('reintentar el mismo lote actualiza resultados sin duplicar ni perder éxitos anteriores',()=>{const s=store(),b=batch('batch-1',[result('a'),result('b','error')]);saveDeliveryBatch(s,b);saveDeliveryBatch(s,{...b,results:[result('a','pending'),result('b')],updatedAt:'2026-10-22T19:01:00Z'});const saved=readDeliveryHistory(s).data;assert.equal(saved.length,1);assert.deepEqual(saved[0].results.map(r=>r.status),['success','success']);assert.equal(saved[0].createdAt,'2026-10-22T19:00:00.000Z');assert.equal(saveDeliveryBatch(s,{...b,revision:9}).ok,false);assert.equal(readDeliveryHistory(s).data[0].revision,8);});
test('un lote interrumpido conserva enlaces confirmados y los pendientes no reciben enlaces inventados',()=>{const s=store();saveDeliveryBatch(s,batch('batch-1',[result('a'),result('b','sending'),result('c','pending'),result('d','error')]));const saved=readDeliveryHistory(s).data[0];assert.equal(saved.results[0].status,'success');for(const r of saved.results.slice(1))assert.equal(r.url,undefined);});
test('un historial corrupto o de otra versión queda intacto al leer y al intentar guardar',()=>{for(const raw of ['{broken',JSON.stringify({version:2,batches:[]})]){const s=store();s.map.set(DELIVERY_HISTORY_KEY,raw);assert.equal(readDeliveryHistory(s).ok,false);assert.equal(saveDeliveryBatch(s,batch()).ok,false);assert.equal(s.map.get(DELIVERY_HISTORY_KEY),raw);}});
test('rechaza enlaces externos, con credenciales, pantalla cruzada o parámetros de redirección',()=>{const base=result().url;for(const url of [base.replace('www.admira.store','evil.test'),base.replace('https://','https://user:pass@'),base.replace('screen=touch','screen=other'),base+'&next=https://evil.test',base+'&loc=other',base.replace('ainimation='+('a'.repeat(64)),'ainimation=bad')]){const s=store();assert.equal(saveDeliveryBatch(s,batch('batch-1',[{...result(),url}])).ok,false);assert.equal(s.map.has(DELIVERY_HISTORY_KEY),false);assert.throws(()=>deliveryHistoryUrl(url,'venue','touch'));}});
test('almacenamiento lleno o denegado no toca proyectos ni descarta la versión guardada',()=>{const s=store();saveDeliveryBatch(s,batch());const before=s.map.get(DELIVERY_HISTORY_KEY);s.setItem=()=>{throw Error('quota');};assert.equal(saveDeliveryBatch(s,batch('batch-2')).ok,false);assert.equal(s.map.get(DELIVERY_HISTORY_KEY),before);assert.equal(s.map.get('project-library'),'unchanged');assert.equal(readDeliveryHistory(undefined).ok,false);});
test('preserva lotes intercalados de distintas vistas y limita el historial a los 30 más recientes',()=>{const s=store();for(let i=0;i<35;i++)assert.equal(saveDeliveryBatch(s,{...batch('batch-'+i),updatedAt:new Date(Date.UTC(2026,9,22,19,i)).toISOString()}).ok,true);const saved=readDeliveryHistory(s).data;assert.equal(saved.length,30);assert.equal(saved[0].id,'batch-34');assert.equal(saved.at(-1).id,'batch-5');assert.equal(s.map.get('project-library'),'unchanged');});
test('CSV incluye sólo el lote elegido, con BOM, acentos, comillas, saltos y resultados pendientes sin enlace',()=>{const b=batch('batch-elegido',[result('a'),result('b','pending'),result('c','error')]);b.projectTitle='Catálogo "táctil", café\nBarcelona';const before=JSON.stringify(b),file=deliveryBatchCsv(b);assert.match(file.filename,/batch-elegido\.csv$/);assert.equal(file.type,'text/csv;charset=utf-8');assert.ok(file.content.startsWith('\ufeff"Fecha (UTC)","Proyecto","Versión"'));assert.match(file.content,/"Catálogo ""táctil"", café\nBarcelona"/);assert.match(file.content,/"Sin confirmación",""\r\n/);assert.match(file.content,/"No preparado",""\r\n/);for(const forbidden of ['must-not-persist','private-owner','secret','not metadata'])assert.ok(!file.content.includes(forbidden));assert.equal(JSON.stringify(b),before);assert.ok(deliveryBatchCsv(b,'en').content.startsWith('\ufeff"Date (UTC)","Project","Version"'));});
test('CSV neutraliza fórmulas tras espacios y controles sin modificar los metadatos originales',()=>{for(const title of ['=1+1','+SUM(1,2)','-1+2','@SUM(A1)','  =HYPERLINK("https://evil.test")','\t=1+1','\r\n+1','\u200b=1','＝1+1']){const b={...batch(),projectTitle:title},csv=deliveryBatchCsv(b).content;const escaped=title.replaceAll('"','""');assert.ok(csv.includes('"\''+escaped+'"'),JSON.stringify(title));assert.equal(b.projectTitle,title);}});
test('CSV falla cerrado ante datos inválidos y enlaces de otra pantalla',()=>{assert.throws(()=>deliveryBatchCsv({...batch(),revision:0}));assert.throws(()=>deliveryBatchCsv(batch('b',[{...result(),url:'javascript:alert(1)'}])));});
test('el resultado del lote nunca presenta pendientes o envíos interrumpidos como completos',()=>{
 assert.equal(deliveryBatchOutcome(batch()),'complete');
 assert.equal(deliveryBatchOutcome(batch('b',[result('a'),result('b','error')])),'error');
 for(const status of ['pending','sending'])assert.equal(deliveryBatchOutcome(batch('b',[result('a'),result('b','error'),result('c',status)])),'unconfirmed');
});
test('búsqueda sin acentos ni distinción de mayúsculas combina proyecto, versión, Xpacio y pantalla sin modificar ni reordenar lotes',()=>{
 const a={...batch('a'),projectId:'project-1-9',projectTitle:'Catálogo café',results:[{...result(),locationName:'Loterías',screenName:'Tótem táctil'}]},b={...batch('b'),revision:9,projectId:'otro-proyecto-8',projectTitle:'Otro catálogo'};
 const all=[b,a],before=JSON.stringify(all);
 for(const query of ['CATALOGO CAFE','versión 8','v8','loterias','TOTEM TACTIL','cafe tactil v8'])assert.deepEqual(filterDeliveryHistory(all,{query}).map(b=>b.id),['a'],query);
 assert.deepEqual(filterDeliveryHistory(all,{query:'version 9'}).map(b=>b.id),['b']);
 assert.deepEqual(filterDeliveryHistory(all,{query:'venue touch',projectId:a.projectId,outcome:'complete'}).map(b=>b.id),['a']);
 assert.deepEqual(filterDeliveryHistory([a,{...a,id:'v80',revision:80}],{query:'v8'}).map(b=>b.id),['a']);
 assert.equal(filterDeliveryHistory(all,{query:'no existe'}).length,0);assert.equal(JSON.stringify(all),before);
});
function historyView(s,language='es',writeClipboard,versionOptions={}){
 const downloads=[],reused=[],doc={documentElement:{lang:language},createElement(tag){return{tag,children:[],dataset:{},setAttribute(k,v){this[k]=v;},append(...nodes){this.children.push(...nodes);},replaceChildren(...nodes){this.children=[...nodes];},addEventListener(){},focus(){this.focused=true;},select(){this.selected=true;},showModal(){this.open=true;},close(){this.open=false;}};}};
 doc.body=doc.createElement('body');const button={},dialog=mountDeliveryHistory({button,storage:s,doc,download:file=>downloads.push(file),onReuse:targets=>reused.push(targets),writeClipboard,...versionOptions});
 const filters=dialog.children.find(n=>n.className==='history-filters'),list=dialog.children.find(n=>n.className==='history-batches');
 return{button,dialog,filters,list,status:dialog.children.find(n=>n.className==='history-filter-status'),query:filters.children[0].children[0],project:filters.children[1].children[0],outcome:filters.children[2].children[0],clear:filters.children[3],downloads,reused};
}
test('filtrar proyectos de igual nombre por ID y resultados mixtos conserva enlaces y acciones del lote exacto, sin escribir',()=>{
 const s=store(),a=batch('a',[result('old')]),b={...batch('b',[result('new'),result('error','error')]),projectId:'other',revision:9,updatedAt:'2026-10-22T20:00:00Z'},c={...batch('c',[result('ok'),result('waiting','sending'),result('failed','error')]),revision:10,updatedAt:'2026-10-22T21:00:00Z'};
 for(const item of [a,b,c])saveDeliveryBatch(s,item);const before=[...s.map],f=historyView(s);f.button.onclick();assert.equal(f.list.children.length,3);assert.match(f.status.textContent,/3 de 3/);assert.equal(f.project.children.length,3);
 f.outcome.value='error';f.outcome.onchange();assert.deepEqual(f.list.children.map(d=>d.dataset.batchId),['b']);assert.match(f.list.children[0].children[0].textContent,/Con errores/);
 action(f.list.children[0],'history-csv').onclick();assert.match(f.downloads[0].filename,/v9-b/);assert.match(f.downloads[0].content,/loc=new/);assert.ok(!f.downloads[0].content.includes('loc=old'));
 action(f.list.children[0],'history-reuse').onclick();assert.deepEqual(f.reused[0].map(t=>t.locationId),['new','error']);assert.equal(f.dialog.open,false);
 f.button.onclick();f.outcome.value='unconfirmed';f.outcome.onchange();assert.deepEqual(f.list.children.map(d=>d.dataset.batchId),['c']);assert.match(f.list.children[0].children[0].textContent,/Sin confirmación/);
 f.clear.onclick();f.project.value='other';f.project.onchange();assert.deepEqual(f.list.children.map(d=>d.dataset.batchId),['b']);
 f.query.value='version 8';f.query.oninput();assert.equal(f.list.children.length,0);assert.match(f.status.textContent,/0 de 3.*No hay lotes/);assert.equal(f.clear.disabled,false);
 f.clear.onclick();assert.equal(f.list.children.length,3);assert.equal(f.clear.disabled,true);assert.deepEqual([...s.map],before);
});
test('búsqueda y filtros se reinician al abrir; historial vacío o corrupto conserva datos y avisa sin filtros falsos',()=>{
 const s=store();saveDeliveryBatch(s,batch());const f=historyView(s,'en');f.button.onclick();f.query.value='none';f.query.oninput();assert.match(f.status.textContent,/0 of 1 batch.*No matching/);f.button.onclick();assert.equal(f.query.value,'');assert.equal(f.list.children.length,1);assert.match(f.list.children[0].children[0].textContent,/Complete/);
 for(const raw of [null,'{broken']){const s=store();if(raw)s.map.set(DELIVERY_HISTORY_KEY,raw);const before=[...s.map],f=historyView(s);f.button.onclick();assert.equal(f.filters.hidden,true);assert.equal(f.list.children.length,0);assert.match(f.status.textContent,raw?/No se puede leer/:/Todavía no hay/);assert.deepEqual([...s.map],before);}
});
