 const b={...batch('b',[{...result('a'),locationName:'Café\nBarcelona',screenName:'Tótem\u202e táctil'},result('b','pending'),result('c','error')]),projectTitle:'Catálogo\nDirector'};const before=JSON.stringify(b),report=deliveryBatchLinks(b);
 assert.equal(report.count,1);assert.equal(report.missing,2);assert.match(report.text,/Catálogo Director · Versión 8/);assert.match(report.text,/1 enlace confirmado · 2 destinos sin enlace/);assert.match(report.text,/Café Barcelona · Tótem táctil\nhttps:\/\//);assert.equal(report.text.match(/https:\/\//g).length,1);
