 const row=entry.children.find(n=>n.tag==='ul').children[0];assert.equal(row.dataset.state,'success');assert.equal(row.children[1].textContent,'Versión preparada');const health=row.children.find(n=>n.className==='history-version-state');assert.equal(health.dataset.versionState,'available');assert.equal(health.textContent,'Versión disponible');assert.equal(check.disabled,false);
