test('motivos de fallo bilingües coinciden entre pantalla y CSV sin exponer errores brutos ni cambiar el preparado',async()=>{
 const cases=[
  {request:async()=>{throw Error('private network token');},es:'Fallo de conexión o consulta',en:'Connection or request failed'},
  {request:async()=>({ok:false,status:503}),es:'Respuesta HTTP 503',en:'HTTP response 503'},
  {request:async()=>({ok:true,status:200,json:async()=>{throw Error('private response body');}}),es:'Datos de respuesta ilegibles',en:'Unreadable response data'},
  {request:()=>new Promise(()=>{}),es:'Tiempo de espera agotado',en:'Time limit exceeded'}
 ];
 for(const language of ['es','en'])for(const item of cases){const s=store();saveDeliveryBatch(s,batch());const before=[...s.map],f=historyView(s,language,undefined,{versionRequest:item.request,versionTimeoutMs:5});f.button.onclick();const entry=f.list.children[0];await action(entry,'history-check').onclick();const row=entry.children.find(n=>n.tag==='ul').children[0],label=row.children.find(n=>n.className==='history-version-state');assert.equal(label.dataset.versionState,'unknown');assert.ok(label.textContent.endsWith(item[language]));assert.ok(!label.textContent.includes('private'));assert.equal(row.dataset.state,'success');
  entry.children.find(n=>n.className==='history-version-csv').onclick();assert.ok(f.downloads[0].content.includes(item[language]));assert.ok(!f.downloads[0].content.includes('private'));assert.deepEqual([...s.map],before);
 }
});
test('cancelar mantiene el historial abierto, aborta las tres peticiones activas y descarta el parcial sin agotar la cola',async()=>{
 const s=store();saveDeliveryBatch(s,batch('b',Array.from({length:5},(_,i)=>result('venue-'+i))));const before=[...s.map],pending=[];const f=historyView(s,'es',undefined,{versionRequest:(url,options)=>new Promise(resolve=>pending.push({url,signal:options.signal,resolve}))});f.button.onclick();const entry=f.list.children[0],check=action(entry,'history-check'),cancel=action(entry,'history-check-cancel'),report=entry.children.find(n=>n.className==='history-version-csv'),summary=entry.children.find(n=>n.className==='history-version-summary');assert.equal(cancel.hidden,true);cancel.onclick();assert.equal(pending.length,0);
 const running=check.onclick();assert.equal(pending.length,3);assert.equal(cancel.hidden,false);assert.equal(cancel.disabled,false);assert.equal(check.disabled,true);pending[0].resolve({ok:true,status:200,json:async()=>versionMeta(8,'venue-0')});await new Promise(setImmediate);assert.equal(pending.length,4);assert.equal(report.hidden,true);
 cancel.onclick();assert.equal(f.dialog.open,true);assert.equal(check.disabled,false);assert.equal(check.focused,true);assert.equal(cancel.hidden,true);assert.equal(cancel.disabled,true);assert.equal(report.hidden,true);assert.match(summary.textContent,/Comprobación cancelada.*otra vez/);assert.equal(summary.dataset.checkedAt,undefined);assert.ok(pending.slice(1).every(p=>p.signal.aborted));assert.ok(entry.children.find(n=>n.tag==='ul').children.every(r=>r.dataset.state==='success'&&r.children.find(n=>n.className==='history-version-state').hidden));
 report.onclick();assert.equal(f.downloads.length,0);await running;for(const p of pending)p.resolve({ok:true,status:200,json:async()=>versionMeta(8,new URL(p.url).pathname)});await Promise.resolve();assert.equal(pending.length,4);assert.match(summary.textContent,/Comprobación cancelada/);assert.equal(f.query.value,'');assert.deepEqual([...s.map],before);
});
test('cancelar e iniciar otra consulta inmediatamente impide que respuestas o finalizadores anteriores cambien el nuevo resultado',async()=>{
 const s=store();saveDeliveryBatch(s,batch());const pending=[];const f=historyView(s,'en',undefined,{versionRequest:(url,options)=>new Promise(resolve=>pending.push({resolve,signal:options.signal}))});f.button.onclick();const entry=f.list.children[0],check=action(entry,'history-check'),cancel=action(entry,'history-check-cancel'),report=entry.children.find(n=>n.className==='history-version-csv'),summary=entry.children.find(n=>n.className==='history-version-summary');
 const first=check.onclick();cancel.onclick();assert.match(summary.textContent,/Check cancelled/);const second=check.onclick();assert.equal(pending.length,2);await first;assert.equal(check.disabled,true);assert.equal(cancel.hidden,false);assert.match(summary.textContent,/Checking versions/);report.onclick();assert.equal(f.downloads.length,0);
 pending[1].resolve({ok:true,status:200,json:async()=>versionMeta()});await second;assert.match(summary.textContent,/Checked.*1 available/);assert.equal(check.disabled,false);assert.equal(cancel.hidden,true);report.onclick();const file=f.downloads[0],checkedAt=summary.dataset.checkedAt;
 pending[0].resolve({ok:false,status:404});await Promise.resolve();await Promise.resolve();assert.equal(summary.dataset.checkedAt,checkedAt);assert.match(summary.textContent,/1 available/);assert.equal(report.hidden,false);assert.equal(cancel.hidden,true);report.onclick();assert.deepEqual(f.downloads[1],file);
 const third=check.onclick();assert.equal(report.hidden,true);cancel.onclick();await third;report.onclick();assert.equal(f.downloads.length,2);assert.equal(summary.dataset.checkedAt,undefined);assert.match(summary.textContent,/Check cancelled/);
});
test('cancelar un lote no cancela ni modifica la consulta de otro; filtros y cierre siguen descartando todas las pendientes',async()=>{
 const s=store();saveDeliveryBatch(s,batch('old',[result('old')]));saveDeliveryBatch(s,{...batch('new',[result('new')]),revision:9,updatedAt:'2026-10-22T20:00:00Z'});const pending=[];const f=historyView(s,'es',undefined,{versionRequest:(url,options)=>new Promise(resolve=>pending.push({resolve,signal:options.signal}))});f.button.onclick();const [newer,older]=f.list.children,a=action(newer,'history-check').onclick(),b=action(older,'history-check').onclick();action(newer,'history-check-cancel').onclick();await a;assert.equal(pending[0].signal.aborted,true);assert.equal(pending[1].signal.aborted,false);assert.equal(action(older,'history-check-cancel').hidden,false);pending[1].resolve({ok:true,status:200,json:async()=>versionMeta(8,'old')});await b;assert.match(older.children.find(n=>n.className==='history-version-summary').textContent,/1 disponible/);assert.match(newer.children.find(n=>n.className==='history-version-summary').textContent,/Comprobación cancelada/);
 const again=action(newer,'history-check').onclick();f.query.value='version 8';f.query.oninput();await again;assert.equal(pending[2].signal.aborted,true);const entry=f.list.children[0];assert.equal(action(entry,'history-check-cancel').hidden,true);const closing=action(entry,'history-check').onclick();f.dialog.children.find(n=>n.tag==='button').onclick();await closing;assert.equal(pending[3].signal.aborted,true);assert.equal(f.dialog.open,false);assert.equal(readDeliveryHistory(s).data.length,2);
});
