test('cada botón exporta exactamente su lote sin acceso, escrituras ni solicitudes',()=>{const s=store();saveDeliveryBatch(s,batch('anterior',[result('old')]));saveDeliveryBatch(s,{...batch('actual',[result('new')]),revision:9,updatedAt:'2026-10-22T20:00:00Z'});const before=[...s.map],downloads=[];const doc={documentElement:{lang:'es'},createElement(tag){return{tag,children:[],dataset:{},setAttribute(k,v){this[k]=v;},append(...nodes){this.children.push(...nodes);},replaceChildren(){this.children=[];},addEventListener(){},showModal(){this.open=true;},close(){this.open=false;}};}};doc.body=doc.createElement('body');const button={},dialog=mountDeliveryHistory({button,storage:s,doc,download:file=>downloads.push(file)});button.onclick();const details=dialog.children.find(n=>n.className==='history-batches').children;for(const entry of details)action(entry,'history-csv').onclick();assert.equal(downloads.length,2);assert.match(downloads[0].filename,/v9-actual/);assert.match(downloads[1].filename,/v8-anterior/);assert.ok(downloads[0].content.includes('loc=new'));assert.ok(!downloads[0].content.includes('loc=old'));assert.ok(downloads[1].content.includes('loc=old'));assert.deepEqual([...s.map],before);});
test('vista de incidencias bilingüe distingue ausencia, consulta fallida y sin enlace; el informe sigue completo sin nuevas consultas ni escrituras',async()=>{
 for(const language of ['es','en']){
  const s=store();saveDeliveryBatch(s,batch('mixed',[result('ok'),result('absent'),result('unknown'),result('pending','pending')]));const before=[...s.map];let requests=0;
  const f=historyView(s,language,undefined,{versionRequest:async url=>{requests++;const id=requests%3;return id===1?{ok:true,status:200,json:async()=>versionMeta(8,'ok')}:{ok:false,status:id===2?404:503};}});f.button.onclick();const entry=f.list.children[0],view=entry.children.find(n=>n.className==='history-version-view'),toggle=view.children[0],matches=view.children[1],scope=entry.children.find(n=>n.className==='history-version-scope'),rows=entry.children.find(n=>n.className==='delivery-results').children,report=entry.children.find(n=>n.className==='history-version-csv');
  assert.equal(view.hidden,true);assert.equal(toggle.disabled,true);await action(entry,'history-check').onclick();assert.equal(view.hidden,false);assert.equal(scope.hidden,false);assert.match(scope.textContent,language==='es'?/incluye todas las pantallas/:/includes all screens/);report.onclick();const full=f.downloads[0];toggle.onclick();assert.equal(toggle['aria-pressed'],'true');assert.deepEqual(rows.map(r=>r.hidden),[true,false,false,false]);assert.match(matches.textContent,language==='es'?/3 de 4 pantallas/:/3 of 4 screens/);assert.deepEqual(rows.slice(1).map(r=>r.children.at(-1).dataset.versionState),['unavailable','unknown','no_link']);report.onclick();assert.deepEqual(f.downloads[1],full);assert.equal(full.content.split('\r\n').length,6);toggle.onclick();assert.ok(rows.every(r=>!r.hidden));assert.equal(toggle['aria-pressed'],'false');assert.equal(requests,3);assert.deepEqual([...s.map],before);
 }
});
