 for(const raw of [null,'{broken']){const s=store();saveDeliveryBatch(s,batch());const f=historyView(s);f.button.onclick();if(raw===null)s.map.delete(DELIVERY_HISTORY_KEY);else s.map.set(DELIVERY_HISTORY_KEY,raw);const before=[...s.map];await f.dialog.children.find(n=>n.className==='history-backup-actions').children[0].onclick();assert.equal(f.downloads.length,0);assert.match(f.dialog.children.find(n=>n.className==='history-backup-status').textContent,raw===null?/No hay lotes/:/No se puede leer el historial/);assert.deepEqual([...s.map],before);}
