test('recuentos visibles usan singular o plural según su cantidad en español e inglés, incluido el denominador',async()=>{
 for(const lang of ['es','en'])for(const n of [0,1,2]){const s=store();for(let i=0;i<n;i++)saveDeliveryBatch(s,batch('b'+i,Array.from({length:n},(_,j)=>result('v'+j))));const pending=[],f=historyView(s,lang,undefined,{versionRequest:()=>new Promise(resolve=>pending.push(resolve))});f.button.onclick();const group=f.dialog.children.find(n=>n.className==='history-backup-actions'),backup=group.children[0],scope=group.children.find(n=>n.className==='history-backup-scope'),backupStatus=f.dialog.children.find(n=>n.className==='history-backup-status');
  if(!n){assert.equal(backup.disabled,true);assert.equal(f.list.children.length,0);continue;}
  const noun=lang==='es'?(n===1?'lote':'lotes'):(n===1?'batch':'batches'),screens=lang==='es'?(n===1?'pantalla':'pantallas'):(n===1?'screen':'screens'),targets=lang==='es'?(n*n===1?'destino':'destinos'):(n*n===1?'target':'targets');assert.ok(scope.textContent.includes(n+' '+noun+' · '+(n*n)+' '+targets));assert.ok(f.status.textContent.includes(n+' '+(lang==='es'?'de':'of')+' '+n+' '+noun));
  await backup.onclick();assert.ok(backupStatus.textContent.includes(n+' '+noun+' · '+(n*n)+' '+targets));const e=f.list.children[0];assert.ok(e.children[0].textContent.includes(n+'/'+n+' '+(lang==='es'?(n===1?'preparado':'preparados'):'prepared')));action(e,'history-csv').onclick();assert.ok(f.status.textContent.includes(n+' '+screens+'.'));
  const checking=action(e,'history-check').onclick(),summary=e.children.find(n=>n.className==='history-version-summary');assert.ok(summary.textContent.includes('0 '+(lang==='es'?'de':'of')+' '+n+' '+(lang==='es'?(n===1?'consulta terminada':'consultas terminadas'):(n===1?'request completed':'requests completed'))));pending.forEach((resolve,i)=>resolve({ok:true,status:200,json:async()=>versionMeta(8,'v'+i)}));await checking;const view=e.children.find(n=>n.className==='history-version-view');view.children[0].onclick();assert.ok(view.children[1].textContent.includes('0 '+(lang==='es'?'de':'of')+' '+n+' '+screens+'.'));e.children.find(n=>n.className==='history-version-csv').onclick();assert.ok(f.status.textContent.includes(n+' '+screens+'.'));
  const u=restoreUi(f);await reviewFile(u,deliveryHistoryBackup(s).content);assert.ok(u.summary.textContent.includes(n+' '+noun+' · '+(n*n)+' '+targets));f.query.value='no-match';f.query.oninput();assert.ok(f.status.textContent.includes('0 '+(lang==='es'?'de':'of')+' '+n+' '+noun+'.'));
 }
});

test('comparación usa identidad exacta, conserva etiquetas renombradas y estados de ambos lotes sin mutar',()=>{
 const a=batch('a',[{...result('same'),locationName:'Antes',screenName:'Antes',status:'pending'},result('equal-name','error'),result('left','sending')]),b={...batch('b',[{...result('same'),locationName:'Después',screenName:'Después'}, {...result('other-id','pending'),locationName:'equal-name'},result('right')]),projectId:'different-project',revision:9};
 const before=JSON.stringify([a,b]),c=compareDeliveryBatchTargets(a,b);assert.equal(c.common.length,1);assert.equal(c.common[0].first.screenName,'Antes');assert.equal(c.common[0].second.screenName,'Después');assert.equal(c.common[0].first.status,'pending');assert.equal(c.common[0].second.status,'success');assert.deepEqual(c.onlyFirst.map(r=>r.locationId),['equal-name','left']);assert.deepEqual(c.onlySecond.map(r=>r.locationId),['other-id','right']);assert.equal(c.onlyFirst[1].status,'sending');assert.equal(JSON.stringify([a,b]),before);assert.ok(!JSON.stringify(c).includes('must-not-persist'));
 const differentScreen={...result('same'),screenId:'another',url:result('same').url.replace('screen=touch','screen=another')};assert.equal(compareDeliveryBatchTargets(batch('a'),batch('b',[differentScreen])).common.length,0);
});
