const csvCells=source=>{const rows=[],row=[];let cell='',quoted=false;for(let i=1;i<source.length;i++){const ch=source[i];if(ch==='"'){if(quoted&&source[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(ch===','&&!quoted){row.push(cell);cell='';}else if(ch==='\r'&&source[i+1]==='\n'&&!quoted){row.push(cell);rows.push([...row]);row.length=0;cell='';i++;}else cell+=ch;}return rows;};
test('CSV de comparación conserva unión exacta, metadatos de ambos lados, estados y campos de destino ausente vacíos',()=>{
 for(const lang of ['es','en']){const first={...batch('a',[result('shared','pending'),result('left','error')]),projectTitle:'Café "Ángel", sur\nPlanta 1'},second={...batch('b',[{...result('shared'),screenName:'Nombre nuevo'},result('right','sending')]),projectId:'another-project',revision:9,createdAt:'2026-10-22T20:00:00Z'};const before=JSON.stringify([first,second]),comparison=compareDeliveryBatchTargets(first,second),file=deliveryComparisonCsv(comparison,lang),rows=csvCells(file.content);assert.ok(file.content.startsWith('\ufeff'));assert.equal(file.type,'text/csv;charset=utf-8');assert.equal(file.destinations,3);assert.equal(rows.length,4);assert.ok(rows.every(r=>r.length===21));assert.deepEqual(rows.slice(1).map(r=>r[1]),['shared','left','right']);assert.equal(rows[1][5],first.projectTitle);assert.equal(rows[1][7],'2026-10-22T19:00:00.000Z');assert.equal(rows[1][16],'2026-10-22T20:00:00.000Z');assert.equal(rows[1][10],lang==='es'?'Pendiente de confirmación':'Awaiting confirmation');assert.equal(rows[1][11],'');assert.equal(rows[1][18],'Nombre nuevo');assert.equal(rows[1][20],result('shared').url);assert.equal(rows[2][10],lang==='es'?'No preparado':'Not prepared');assert.deepEqual(rows[2].slice(17),['','','','']);assert.deepEqual(rows[3].slice(8,12),['','','','']);assert.equal(rows[3][19],lang==='es'?'Envío sin confirmar':'Delivery unconfirmed');assert.equal(JSON.stringify([first,second]),before);for(const forbidden of ['must-not-persist','secret','private-owner'])assert.ok(!file.content.includes(forbidden));}
});
