const compareSearchUi=f=>{const u=exclusiveUi(f),search=u.group.children.find(n=>n.className==='history-compare-search');return{...u,search,query:search.children[0].children[0],clearSearch:search.children[1],visible:()=>u.groups().flatMap(g=>g.hidden?[]:g.children[1].children.filter(li=>!li.hidden))};};
const setComparisonQuery=(u,value)=>{u.query.value=value;u.query.oninput();};
const compareOrderUi=f=>{const u=compareSearchUi(f),orderControl=u.view.children.find(n=>n.className==='history-compare-order-control');return{...u,orderControl,order:orderControl.children[0],ids:()=>u.groups().map(g=>g.children[1].children.map(li=>li.children[0].dataset.locationId+'/'+li.children[0].dataset.screenId))};};
const setComparisonOrder=(u,value)=>{u.order.value=value;u.order.onchange();};
const compareSwapUi=f=>{const u=compareOrderUi(f);return{...u,swap:u.group.children.find(n=>n.className==='history-compare-controls').children.find(n=>n.className==='history-compare-swap'),labels:()=>u.group.children.find(n=>n.className==='history-compare-controls').children.slice(0,2).map(n=>n.children[1].textContent)};};
const selectComparisonPair=(u,first,second)=>{u.first.value=first;u.second.value=second;u.first.onchange();u.second.onchange();};
const compareStatesUi=f=>{const u=compareSwapUi(f);return{...u,stateSummary:u.group.children.find(n=>n.className==='history-compare-state-summary'),marks:()=>u.groups().flatMap(g=>g.children[1].children.flatMap(li=>li.children.filter(n=>n.className==='history-compare-saved-state')))};};
const differentStatesUi=f=>compareStatesUi(f);
test('seleccionar directamente las tres vistas conserva búsqueda/orden y resumen, y exporta la unión exacta sin operaciones',async()=>{
 for(const lang of ['es','en']){const s=store();saveDeliveryBatch(s,batch('a',[result('z','pending'),result('a','sending'),result('left','error')]));saveDeliveryBatch(s,batch('b',[{...result('z'),screenName:'Renombrada'},result('a','error'),result('right','pending')]));let requests=0,copies=0;const f=historyView(s,lang,async()=>copies++,{versionRequest:async()=>requests++});f.button.onclick();const u=compareStatesUi(f);selectComparisonPair(u,'a','b');u.button.onclick();await u.download.onclick();const full=f.downloads[0],before=[...s.map],summary=u.stateSummary.textContent,totals=u.totals.textContent;setComparisonOrder(u,'name');setComparisonQuery(u,'z');for(const [value,count] of [['all',1],['exclusive',0],['different',1]]){setComparisonView(u,value);assert.equal(u.visible().length,count);assert.equal(u.query.value,'z');assert.equal(u.order.value,'name');assert.equal(u.viewSelect.value,value);assert.equal(u.stateSummary.textContent,summary);assert.equal(u.totals.textContent,totals);await u.download.onclick();assert.deepEqual(f.downloads.at(-1),full);}u.clearSearch.onclick();assert.equal(u.viewSelect.value,'different');assert.deepEqual(u.visible().map(li=>li.children[0].dataset.locationId),['a','z']);setComparisonView(u,'exclusive');assert.equal(u.visible().length,2);setComparisonView(u,'all');assert.equal(u.visible().length,4);assert.equal(requests,0);assert.equal(copies,0);assert.deepEqual([...s.map],before);}
});
