test('cambio de pareja, filtros, cierre, refresco, nueva comparación e invalidación retiran y reinician el orden',async()=>{
 for(const change of ['pair','filter','close','refresh','compare','saved']){const s=store();for(const id of ['a','b','c'])saveDeliveryBatch(s,batch(id,[result(id)]));const f=historyView(s);f.button.onclick();const u=compareOrderUi(f);u.first.value='a';u.second.value='b';u.button.onclick();setComparisonOrder(u,'name');setComparisonQuery(u,'missing');toggleComparisonView(u,'exclusive');if(change==='pair'){u.second.value='c';u.second.onchange();}if(change==='filter'){f.query.value='none';f.query.oninput();}if(change==='close')f.dialog.children.find(n=>n.tag==='button').onclick();if(change==='refresh')f.button.onclick();if(change==='compare')u.button.onclick();if(change==='saved'){saveDeliveryBatch(s,batch('changed'));await u.download.onclick();}if(change!=='compare'){assert.equal(u.orderControl.hidden,true);assert.equal(u.order.disabled,true);assert.equal(u.order.value,'original');setComparisonOrder(u,'name');assert.equal(u.orderControl.hidden,true);f.button.onclick();u.first.value='a';u.second.value='c';u.button.onclick();}assert.equal(u.orderControl.hidden,false);assert.equal(u.order.disabled,false);assert.equal(u.order.value,'original');assert.equal(u.query.value,'');assert.equal(String(u.viewSelect.value==='exclusive'),'false');}
});
